// === Tab: mySketch ===
// なんか高さで色変えるんだって
// で、sinのsinだって。多分周期はPIずらして掛け算する

let flip = 0; // set flip = 1 before saving an image or thumbnail; then set flip = 0.
let gl;
let buf; // bufは必要

let count = 0;

let myShader;
let vs =
`
precision mediump float; // これがないと両方でuCount使えなくてエラーになる
attribute vec3 aPosition;
uniform float uPointSize;
uniform float uCount;
uniform float uDistanceFactor;
const float TAU = 6.28318;
varying float vStrokeWeight;
varying vec3 vPosition;
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

float func(vec2 p){
  return 0.6 * sin(TAU * p.x) * sin(TAU * (p.y + 0.5));
}

void main() {
  vec3 p = aPosition;
  p = -1.0 + 2.0 * p;
  p.z = func(p.xy + vec2(0.6, 0.8) * uCount / 720.0);
  vPosition = p;
  vec4 positionVec4 =  vec4(p * uDistanceFactor, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
  float sizeFactor = 0.5 + abs(sin(p.y * 3371.412));
  gl_PointSize = uPointSize * sizeFactor;
  vStrokeWeight = uPointSize * sizeFactor;
}
`
let fs =
`
precision mediump float;
precision mediump int;
uniform vec4 uMaterialColor;
uniform float uCount;
const float TAU = 6.28318;
varying float vStrokeWeight;
varying vec3 vPosition;

// getRGB,参上！
vec3 getRGB(float h, float s, float b){
    vec3 c = vec3(h, s, b);
    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    rgb = rgb * rgb * (3.0 - 2.0 * rgb);
    return c.z * mix(vec3(1.0), rgb, c.y);
}

void main(){
  float mask = 0.0;

  // make a circular mask using the gl_PointCoord (goes from 0 - 1 on a point)
  // might be able to get a nicer edge on big strokeweights with smoothstep but slightly less performant

  mask = step(0.98, length(gl_PointCoord * 2.0 - 1.0));

  // if strokeWeight is 1 or less lets just draw a square
  // this prevents weird artifacting from carving circles when our points are really small
  // if strokeWeight is larger than 1, we just use it as is

  mask = mix(0.0, mask, clamp(floor(vStrokeWeight - 0.5),0.0,1.0));

  // throw away the borders of the mask
  // otherwise we get weird alpha blending issues

  if(mask > 0.98){
    discard;
  }
  float properCount = uCount + abs(sin(vPosition.x * 3312.749)) * 360.0;
  float hue = (0.6 - vPosition.z) / 1.4 - 0.05;
  float sat = 1.0 - length(vPosition.xy) * 0.5;
  gl_FragColor = vec4(getRGB(hue, sat, 1.0) * (1.0 - mask), 1.0);
}
`

function setup(){
  let _gl=createCanvas(1112, 834, WEBGL);
  gl = this._renderer.GL
  pixelDensity(1);
  myShader = createShader(vs, fs);
  shader(myShader);
  stroke(255);
  strokeWeight(3);
  myShader.isPointShader = () => true;
  _gl.userPointShader = myShader;
}

function draw(){
	if (flip == 1) scale(1, -1);
  let start = millis();
  background(0);
  rotateX(PI * 0.6 / 2);
  rotateZ(-TAU * count / 600);
  myShader.setUniform("uCount", count);
  const DISTANCE_FACTOR = max(width, height) * 0.45;
  myShader.setUniform("uDistanceFactor", DISTANCE_FACTOR);
  myPoints(100);
  count++;
  let end = millis();
  //if(count%60==0){console.log((end-start)*60/1000);}
}

function myPoints(detail){
  const gId = `myPoints|${detail}`;
  if(!this._renderer.geometryInHash(gId)){
    const myPointsGeom = new p5.Geometry();
    let v = createVector();
    for(let i = 0; i <= detail ; i++){
      for(let j = 0; j <= detail; j++){
        // もはやただのノイズ
        // 1より大きい値にすればidにできるね・・0.01～0.99に落とすとかして。何でもできる。自由自在。
        let x = i / detail;
        let y = j / detail;
        myPointsGeom.vertices.push(v.set(x, y, 0).copy());
      }
    }
    buf = this._renderer.createBuffers(gId, myPointsGeom);
  }
  // これでいいんだ
  this._renderer._drawPoints(buf.model.vertices, this._renderer.immediateMode.buffers.point);
}

let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save('pix.jpg');
    lapse = millis();
  }
}

